// Check expiry dates and categorize urgency
const now = new Date();
const results = [];

for (const item of $input.all()) {
  const fields = item.json.fields || item.json;
  const expiryRaw = fields['Expiry Date'] || fields['expiry_date'] || fields['End Date'] || fields['end_date'] || null;

  if (!expiryRaw) continue; // skip contracts with no expiry date

  const expiryDate = new Date(expiryRaw);
  if (isNaN(expiryDate.getTime())) continue; // skip invalid dates

  const diffMs = expiryDate.getTime() - now.getTime();
  const daysRemaining = Math.ceil(diffMs / (1000 * 60 * 60 * 24));

  let alertType = 'ok';
  if (daysRemaining <= 0) {
    alertType = 'expired';
  } else if (daysRemaining <= 30) {
    alertType = 'critical';
  } else if (daysRemaining <= 60) {
    alertType = 'warning';
  } else if (daysRemaining <= 90) {
    alertType = 'notice';
  }

  results.push({
    json: {
      id: item.json.id || fields.id || 'unknown',
      contract_name: fields['Contract Name'] || fields['contract_name'] || fields['Name'] || fields['name'] || 'Unnamed',
      vendor: fields['Vendor'] || fields['vendor'] || fields['Party'] || fields['party'] || 'Unknown',
      expiry_date: expiryRaw,
      days_remaining: daysRemaining,
      alert_type: alertType,
      risk_score: fields['Risk Score'] || fields['risk_score'] || null,
      value: fields['Contract Value'] || fields['contract_value'] || fields['Value'] || null,
      status: fields['Status'] || fields['status'] || 'Unknown'
    }
  });
}

// Sort by days_remaining ascending (most urgent first)
results.sort((a, b) => a.json.days_remaining - b.json.days_remaining);

return results.length > 0 ? results : [{ json: { _empty: true, alert_type: 'ok', days_remaining: 999 } }];

// Build alert summary — combines expiring contracts + open high-risk concerns + SLA breaches
const allItems = $input.all();

// Separate items by source — items from merge node carry different shapes
// Filter - Expiring Soon items have alert_type and days_remaining
// Airtable - Get Open Concerns items have fields with Risk Level
// Check SLA Breaches items have breaches array
let expiringContracts = [];
let concerns = [];
let slaData = { breaches: [], credits: [], breach_count: 0, credit_count: 0 };

for (const item of allItems) {
  const j = item.json;
  if (j.breaches !== undefined) {
    // SLA breach data
    slaData = j;
  } else if (j.alert_type && j.days_remaining !== undefined && !j._empty) {
    // Expiring contract
    expiringContracts.push(item);
  } else if (j.fields || j['Risk Level'] || j['risk_level'] || j['Concern'] || j['concern']) {
    // Concern record
    concerns.push(item);
  }
}

const now = new Date().toISOString().split('T')[0];

// Group expiring contracts by urgency
const expired = expiringContracts.filter(i => i.json.alert_type === 'expired');
const critical = expiringContracts.filter(i => i.json.alert_type === 'critical');
const warning = expiringContracts.filter(i => i.json.alert_type === 'warning');
const notice = expiringContracts.filter(i => i.json.alert_type === 'notice');

// --- Plain text version ---
let plain = `SLA Contract Manager — Daily Alert Digest\nGenerated: ${now}\n`;
plain += `${'='.repeat(50)}\n\n`;

function formatContractLine(c) {
  return `  - ${c.json.contract_name} (${c.json.vendor}) — expires ${c.json.expiry_date} (${c.json.days_remaining} days)${c.json.risk_score ? ' [Risk: ' + c.json.risk_score + ']' : ''}`;
}

plain += `SECTION 1: CONTRACTS EXPIRING SOON\n`;
plain += `${'-'.repeat(40)}\n`;

if (expired.length > 0) {
  plain += `\n🔴 EXPIRED (${expired.length}):\n`;
  expired.forEach(c => { plain += formatContractLine(c) + '\n'; });
}
if (critical.length > 0) {
  plain += `\n🔴 CRITICAL — within 30 days (${critical.length}):\n`;
  critical.forEach(c => { plain += formatContractLine(c) + '\n'; });
}
if (warning.length > 0) {
  plain += `\n🟡 WARNING — within 60 days (${warning.length}):\n`;
  warning.forEach(c => { plain += formatContractLine(c) + '\n'; });
}
if (notice.length > 0) {
  plain += `\n🟢 NOTICE — within 90 days (${notice.length}):\n`;
  notice.forEach(c => { plain += formatContractLine(c) + '\n'; });
}
if (expiringContracts.length === 0) {
  plain += `\n  No contracts expiring within 90 days.\n`;
}

plain += `\nSECTION 2: HIGH-RISK OPEN CONCERNS\n`;
plain += `${'-'.repeat(40)}\n`;
if (concerns.length > 0) {
  concerns.forEach(c => {
    const f = c.json.fields || c.json;
    plain += `  - ${f['Concern'] || f['concern'] || f['Description'] || f['description'] || 'No description'}`;
    if (f['Contract Name'] || f['contract_name']) plain += ` (Contract: ${f['Contract Name'] || f['contract_name']})`;
    plain += '\n';
  });
} else {
  plain += `  No high-risk open concerns.\n`;
}

plain += `\nSECTION 3: SLA BREACHES\n`;
plain += `${'-'.repeat(40)}\n`;
if (slaData.breaches.length > 0) {
  for (const b of slaData.breaches) {
    plain += `  - ${b.contract_name} (${b.period}): actual ${b.actual_uptime}% vs target ${b.target_uptime}% (gap: ${b.gap}%)${b.credit_triggered ? ' [CREDIT TRIGGERED]' : ''}\n`;
  }
} else {
  plain += `  No SLA breaches detected.\n`;
}

if (slaData.credits.length > 0) {
  plain += `\nSECTION 4: SERVICE CREDITS TRIGGERED\n`;
  plain += `${'-'.repeat(40)}\n`;
  for (const cr of slaData.credits) {
    plain += `  - ${cr.contract_name} (${cr.period}): actual ${cr.actual_uptime}% vs target ${cr.target_uptime}%\n`;
  }
}

plain += `\nSECTION 5: SUMMARY\n`;
plain += `${'-'.repeat(40)}\n`;
plain += `  Expired:  ${expired.length}\n`;
plain += `  Critical: ${critical.length}\n`;
plain += `  Warning:  ${warning.length}\n`;
plain += `  Notice:   ${notice.length}\n`;
plain += `  High-risk concerns: ${concerns.length}\n`;
plain += `  SLA breaches: ${slaData.breach_count}\n`;
plain += `  Service credits triggered: ${slaData.credit_count}\n`;
plain += `  Total alerts: ${expiringContracts.length + concerns.length + slaData.breach_count}\n`;

// --- HTML version ---
function escHtml(s) { return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

function contractRow(c) {
  const color = c.json.alert_type === 'expired' ? '#dc2626' : c.json.alert_type === 'critical' ? '#dc2626' : c.json.alert_type === 'warning' ? '#d97706' : '#16a34a';
  return `<tr>
    <td style="padding:6px 12px;border-bottom:1px solid #e5e7eb;">${escHtml(c.json.contract_name)}</td>
    <td style="padding:6px 12px;border-bottom:1px solid #e5e7eb;">${escHtml(c.json.vendor)}</td>
    <td style="padding:6px 12px;border-bottom:1px solid #e5e7eb;">${escHtml(c.json.expiry_date)}</td>
    <td style="padding:6px 12px;border-bottom:1px solid #e5e7eb;font-weight:bold;color:${color};">${c.json.days_remaining} days</td>
    <td style="padding:6px 12px;border-bottom:1px solid #e5e7eb;">${c.json.risk_score || '—'}</td>
  </tr>`;
}

let html = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:700px;margin:0 auto;">`;
html += `<h1 style="color:#1e293b;border-bottom:3px solid #3b82f6;padding-bottom:8px;">SLA Contract Manager</h1>`;
html += `<p style="color:#64748b;">Daily Alert Digest — ${now}</p>`;

// Expiring contracts table
html += `<h2 style="color:#1e293b;margin-top:24px;">Contracts Expiring Soon</h2>`;
if (expiringContracts.length > 0) {
  html += `<table style="width:100%;border-collapse:collapse;font-size:14px;">`;
  html += `<thead><tr style="background:#f1f5f9;">`;
  html += `<th style="padding:8px 12px;text-align:left;">Contract</th>`;
  html += `<th style="padding:8px 12px;text-align:left;">Vendor</th>`;
  html += `<th style="padding:8px 12px;text-align:left;">Expiry</th>`;
  html += `<th style="padding:8px 12px;text-align:left;">Remaining</th>`;
  html += `<th style="padding:8px 12px;text-align:left;">Risk</th>`;
  html += `</tr></thead><tbody>`;
  [...expired, ...critical, ...warning, ...notice].forEach(c => { html += contractRow(c); });
  html += `</tbody></table>`;
} else {
  html += `<p style="color:#16a34a;">No contracts expiring within 90 days.</p>`;
}

// High-risk concerns
html += `<h2 style="color:#1e293b;margin-top:24px;">High-Risk Open Concerns</h2>`;
if (concerns.length > 0) {
  html += `<ul style="font-size:14px;">`;
  concerns.forEach(c => {
    const f = c.json.fields || c.json;
    const desc = f['Concern'] || f['concern'] || f['Description'] || f['description'] || 'No description';
    const contract = f['Contract Name'] || f['contract_name'] || '';
    html += `<li style="margin-bottom:6px;"><strong>${escHtml(desc)}</strong>${contract ? ' — ' + escHtml(contract) : ''}</li>`;
  });
  html += `</ul>`;
} else {
  html += `<p style="color:#16a34a;">No high-risk open concerns.</p>`;
}

// SLA Breaches section
html += `<h2 style="color:#1e293b;margin-top:24px;">SLA Breaches</h2>`;
if (slaData.breaches.length > 0) {
  html += `<table style="width:100%;border-collapse:collapse;font-size:14px;">`;
  html += `<thead><tr style="background:#fef2f2;">`;
  html += `<th style="padding:8px 12px;text-align:left;color:#dc2626;">Contract</th>`;
  html += `<th style="padding:8px 12px;text-align:left;color:#dc2626;">Period</th>`;
  html += `<th style="padding:8px 12px;text-align:left;color:#dc2626;">Actual</th>`;
  html += `<th style="padding:8px 12px;text-align:left;color:#dc2626;">Target</th>`;
  html += `<th style="padding:8px 12px;text-align:left;color:#dc2626;">Gap</th>`;
  html += `<th style="padding:8px 12px;text-align:left;color:#dc2626;">Credit?</th>`;
  html += `</tr></thead><tbody>`;
  for (const b of slaData.breaches) {
    html += `<tr style="background:#fef2f2;">`;
    html += `<td style="padding:6px 12px;border-bottom:1px solid #fecaca;color:#dc2626;font-weight:bold;">${escHtml(b.contract_name)}</td>`;
    html += `<td style="padding:6px 12px;border-bottom:1px solid #fecaca;">${escHtml(b.period)}</td>`;
    html += `<td style="padding:6px 12px;border-bottom:1px solid #fecaca;color:#dc2626;font-weight:bold;">${b.actual_uptime}%</td>`;
    html += `<td style="padding:6px 12px;border-bottom:1px solid #fecaca;">${b.target_uptime}%</td>`;
    html += `<td style="padding:6px 12px;border-bottom:1px solid #fecaca;color:#dc2626;font-weight:bold;">${b.gap}%</td>`;
    html += `<td style="padding:6px 12px;border-bottom:1px solid #fecaca;">${b.credit_triggered ? '⚠️ YES' : 'No'}</td>`;
    html += `</tr>`;
  }
  html += `</tbody></table>`;
} else {
  html += `<p style="color:#16a34a;">No SLA breaches detected.</p>`;
}

// Service Credits Triggered
if (slaData.credits.length > 0) {
  html += `<h2 style="color:#b91c1c;margin-top:24px;">⚠️ Service Credits Triggered</h2>`;
  html += `<ul style="font-size:14px;">`;
  for (const cr of slaData.credits) {
    html += `<li style="margin-bottom:6px;color:#dc2626;"><strong>${escHtml(cr.contract_name)}</strong> (${escHtml(cr.period)}): actual ${cr.actual_uptime}% vs target ${cr.target_uptime}%</li>`;
  }
  html += `</ul>`;
}

// Summary stats
html += `<div style="margin-top:24px;padding:16px;background:#f8fafc;border-radius:8px;border:1px solid #e2e8f0;">`;
html += `<h3 style="margin-top:0;color:#1e293b;">Summary</h3>`;
html += `<table style="font-size:14px;">`;
html += `<tr><td style="padding:2px 16px 2px 0;color:#dc2626;font-weight:bold;">Expired:</td><td>${expired.length}</td></tr>`;
html += `<tr><td style="padding:2px 16px 2px 0;color:#dc2626;font-weight:bold;">Critical (&lt;30d):</td><td>${critical.length}</td></tr>`;
html += `<tr><td style="padding:2px 16px 2px 0;color:#d97706;font-weight:bold;">Warning (&lt;60d):</td><td>${warning.length}</td></tr>`;
html += `<tr><td style="padding:2px 16px 2px 0;color:#16a34a;">Notice (&lt;90d):</td><td>${notice.length}</td></tr>`;
html += `<tr><td style="padding:2px 16px 2px 0;">High-risk concerns:</td><td>${concerns.length}</td></tr>`;
html += `<tr><td style="padding:2px 16px 2px 0;color:#dc2626;">SLA breaches:</td><td>${slaData.breach_count}</td></tr>`;
html += `<tr><td style="padding:2px 16px 2px 0;color:#b91c1c;">Service credits:</td><td>${slaData.credit_count}</td></tr>`;
html += `<tr><td style="padding:2px 16px 2px 0;font-weight:bold;">Total alerts:</td><td><strong>${expiringContracts.length + concerns.length + slaData.breach_count}</strong></td></tr>`;
html += `</table></div>`;

html += `<p style="margin-top:24px;font-size:12px;color:#94a3b8;">Generated by Contract Pulse SLA Monitor</p>`;
html += `</div>`;

const hasAlerts = expiringContracts.length > 0 || concerns.length > 0 || slaData.breach_count > 0;

return [{
  json: {
    has_alerts: hasAlerts,
    total_alerts: expiringContracts.length + concerns.length + slaData.breach_count,
    expired_count: expired.length,
    critical_count: critical.length,
    warning_count: warning.length,
    notice_count: notice.length,
    concerns_count: concerns.length,
    sla_breach_count: slaData.breach_count,
    credit_count: slaData.credit_count,
    plain_text: plain,
    html_body: html,
    generated_at: new Date().toISOString()
  }
}];

// Log the alert for audit trail
const summary = $input.item.json;
const logEntry = {
  event: 'sla_alert_digest_sent',
  timestamp: new Date().toISOString(),
  total_alerts: summary.total_alerts || 0,
  expired: summary.expired_count || 0,
  critical: summary.critical_count || 0,
  warning: summary.warning_count || 0,
  notice: summary.notice_count || 0,
  high_risk_concerns: summary.concerns_count || 0,
  has_alerts: summary.has_alerts || false,
  generated_at: summary.generated_at || new Date().toISOString()
};

console.log('SLA Alert Digest:', JSON.stringify(logEntry));

return [{ json: logEntry }];

// Check SLA breaches and credit-triggered items from Uptime Log
const records = $input.all();
const breaches = [];
const credits = [];

for (const item of records) {
  const f = item.json.fields || item.json;

  const breach = f['Breach'] === true || f['breach'] === true || f['Breach'] === 'true';
  const creditTriggered = f['Credit Triggered'] === true || f['credit_triggered'] === true || f['Credit Triggered'] === 'true';
  const actualUptime = parseFloat(f['Actual Uptime'] || f['actual_uptime'] || 0);
  const targetUptime = parseFloat(f['Target Uptime'] || f['target_uptime'] || 0);
  const contractName = f['Contract Name'] || f['contract_name'] || f['Name'] || f['name'] || 'Unknown';
  const period = f['Period'] || f['period'] || f['Month'] || f['month'] || 'Unknown';
  const gap = targetUptime - actualUptime;

  if (breach || actualUptime < targetUptime) {
    breaches.push({
      contract_name: contractName,
      period: period,
      actual_uptime: actualUptime,
      target_uptime: targetUptime,
      gap: Math.round(gap * 1000) / 1000,
      credit_triggered: creditTriggered
    });
  }

  if (creditTriggered) {
    credits.push({
      contract_name: contractName,
      period: period,
      actual_uptime: actualUptime,
      target_uptime: targetUptime
    });
  }
}

// Group breaches by contract
const grouped = {};
for (const b of breaches) {
  if (!grouped[b.contract_name]) grouped[b.contract_name] = [];
  grouped[b.contract_name].push(b);
}

return [{
  json: {
    breaches: breaches,
    credits: credits,
    grouped_breaches: grouped,
    breach_count: breaches.length,
    credit_count: credits.length
  }
}];
